//! Filter admission fixtures generated by the production query compiler.
use crate::auth::PrincipalCtx;
use crate::query::{Query, compile_query};
use crate::schema::SchemaDef;
use serde_json::{Value, json};

/// Enumerate field types, operators, and operand shapes on both storage paths.
pub fn render_filter_operators_spec() -> Result<String, serde_json::Error> {
    let types = [
        ("string", json!({"type":"string"})),
        ("number", json!({"type":"number"})),
        ("boolean", json!({"type":"boolean"})),
        ("int64", json!({"type":"int64"})),
        ("id", json!({"type":"id","table":"items"})),
        ("bytes", json!({"type":"bytes"})),
        ("null", json!({"type":"null"})),
        ("any", json!({"type":"any"})),
        ("literal", json!({"type":"literal","value":"x"})),
        (
            "union",
            json!({"type":"union","variants":[{"type":"string"},{"type":"number"}]}),
        ),
        ("array", json!({"type":"array","element":{"type":"string"}})),
        (
            "array-id",
            json!({"type":"array","element":{"type":"id","table":"items"}}),
        ),
        (
            "array-number",
            json!({"type":"array","element":{"type":"number"}}),
        ),
        (
            "optional-array",
            json!({"type":"optional","inner":{"type":"array","element":{"type":"string"}}}),
        ),
        (
            "string-union",
            json!({"type":"union","variants":[{"type":"literal","value":"x"},{"type":"literal","value":"y"}]}),
        ),
        (
            "object",
            json!({"type":"object","fields":{"a":{"type":"string"}}}),
        ),
        ("record", json!({"type":"record","value":{"type":"string"}})),
        ("vector", json!({"type":"vector","dimensions":2})),
        (
            "optional",
            json!({"type":"optional","inner":{"type":"string"}}),
        ),
    ];
    let operands = [
        ("string", json!("x")),
        ("decimal-string", json!("3")),
        ("number", json!(3)),
        ("fraction", json!(1.5)),
        ("boolean", json!(true)),
        ("null", Value::Null),
        ("array", json!(["x"])),
        ("object", json!({"a":"x"})),
    ];
    let mut rows = Vec::new();
    for (name, ty) in types {
        for indexed in [false, true] {
            // Only scalar-column-compatible types can be indexed.
            if indexed
                && !matches!(
                    name,
                    "string"
                        | "number"
                        | "boolean"
                        | "int64"
                        | "id"
                        | "literal"
                        | "optional"
                        | "string-union"
                )
            {
                continue;
            }
            let indexes = if indexed {
                json!([{"name":"by_v","fields":["v"]}])
            } else {
                json!([])
            };
            let schema_json = json!({"tables":{"items":{"fields":{"v":ty},"indexes":indexes}}});
            let schema: SchemaDef = serde_json::from_value(schema_json.clone())?;
            let mut filters = Vec::new();
            for op in ["eq", "neq", "gt", "gte", "lt", "lte", "contains", "in"] {
                for (shape, value) in &operands {
                    let filter = if op == "in" {
                        json!({"op":op,"field":"v","values":[value]})
                    } else {
                        json!({"op":op,"field":"v","value":value})
                    };
                    filters.push((format!("{op}-{shape}"), filter));
                }
            }
            filters.extend([
                (
                    "in-empty".into(),
                    json!({"op":"in","field":"v","values":[]}),
                ),
                (
                    "in-mixed".into(),
                    json!({"op":"in","field":"v","values":["x",3]}),
                ),
                ("exists".into(), json!({"op":"exists","field":"v"})),
                (
                    "olderThan".into(),
                    json!({"op":"olderThan","field":"v","ms":1000}),
                ),
                (
                    "unknown-field".into(),
                    json!({"op":"eq","field":"missing","value":"x"}),
                ),
            ]);
            for (case, filter) in filters {
                let query_json = json!({"table":"items","filter":filter});
                let query: Query = serde_json::from_value(query_json.clone())?;
                let expect = match compile_query(
                    "spec_filters",
                    &schema,
                    &query,
                    &PrincipalCtx::bypass(),
                    false,
                ) {
                    Ok(_) => json!({"accepted":true}),
                    Err(error) => json!({"error":{"code":error.code}}),
                };
                rows.push(json!({"id":format!("{name}-{}-{case}", if indexed {"indexed"} else {"unindexed"}),"schema":schema_json,"query":query_json,"expect":expect}));
            }
        }
    }
    let mut out = serde_json::to_string_pretty(&json!({
        "$comment":"GENERATED by make gen-spec-filter-operators calling production query::compile_query / compile_filter. Clients assert admission and error codes on empty engines.",
        "rows":rows
    }))?;
    out.push('\n');
    Ok(out)
}
